/**
 * Engine unit suite. Pure functions only — no model, no device, no plugin host.
 *
 * The engine is the referee, so the tests are the referee's rulebook: they pin
 * the properties that make the game fair rather than the exact numbers that
 * make it balanced. Balance numbers will move; these invariants must not.
 *
 *   · The RNG is deterministic and lives in the save (no reroll-by-reload).
 *   · A model hint can never make a check automatic or impossible.
 *   · A moral choice is never rolled, never vetoed, only priced.
 *   · Counters are bounded and never wrap.
 *   · The save round-trips and old saves migrate forward.
 *
 * Run from the payload root so the package resolves its siblings:
 *   cd .build/payload/profile-ohos/profiles/ohos/node_modules/@ohos/dsh-sanguo
 *   node --test test/*.test.mjs
 */
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'

import { nextState, rollDie, rollDice, rollCheck, pickOne, seedFrom } from '../engine/rng.js'
import {
  check, weigh, applyEffects, clampDifficulty, clampAttribute, outcomeOf,
  normaliseEffects, COUNTER_KEYS, RESOURCE_KEYS, DIFFICULTY_BANDS, OUTCOME
} from '../engine/adjudicate.js'
import {
  priceChoice, decay, describe, pressureOf, isDeparture,
  DRIFT_MAX, PRESSURE_CAP, DRIFT_PER_DEVIATION
} from '../engine/destiny.js'
import {
  createSave, migrate, save, load, exists, appendHistory, readHistory, SCHEMA, clamp
} from '../engine/state.js'
import { advance, ageAt, formatDate, eraOf, seasonOfTurn, monthOfTurn, seasonsUntilAge } from '../engine/clock.js'
import {
  instantiate, remember, dispositionOf, stanceLabel, ensurePerson, putPerson,
  driftMoods, MEMORY_LIMIT, PEOPLE
} from '../engine/people.js'
import { buildDigest, renderDigest, nearestPeople, recentEvents, LIMITS } from '../engine/digest.js'
import {
  indexActs, findScene, currentScene, chooseBranch, attemptScene, advanceWorld,
  nextCursor, describeScene, pushLog, seedFactions, rosterOf
} from '../engine/acts.js'
import { advanceFactions, INITIAL_FACTIONS, ADJACENCY, powerModifier, syncPlayerFaction, isActive } from '../engine/world.js'

// ---------------------------------------------------------------------------
// RNG
// ---------------------------------------------------------------------------

test('rng: same seed replays the same stream', () => {
  let a = seedFrom('liubei')
  let b = seedFrom('liubei')
  for (let index = 0; index < 50; index += 1) {
    const ra = rollDie(a, 100)
    const rb = rollDie(b, 100)
    assert.equal(ra.value, rb.value)
    a = ra.state
    b = rb.state
  }
})

test('rng: different seeds diverge', () => {
  const a = seedFrom('liubei')
  const b = seedFrom('caocao')
  assert.notEqual(a, b)
})

test('rng: a zero state escapes the xorshift fixed point', () => {
  // 0 is a fixed point of xorshift32; a corrupt save with seed 0 must still roll.
  const first = nextState(0)
  assert.notEqual(first, 0)
  const second = nextState(first)
  assert.notEqual(second, first)
})

test('rng: dice stay in range and cover it', () => {
  let state = seedFrom('range')
  const seen = new Set()
  for (let index = 0; index < 2000; index += 1) {
    const rolled = rollDie(state, 6)
    state = rolled.state
    assert.ok(rolled.value >= 1 && rolled.value <= 6, `out of range: ${rolled.value}`)
    seen.add(rolled.value)
  }
  assert.equal(seen.size, 6, 'every face should appear')
})

test('rng: rollDice sums its faces and advances once per die', () => {
  let state = seedFrom('dice')
  const rolled = rollDice(state, 3, 6)
  assert.equal(rolled.faces.length, 3)
  assert.equal(rolled.total, rolled.faces.reduce((sum, face) => sum + face, 0))
  assert.notEqual(rolled.state, state)
})

test('rng: pickOne is deterministic and in range', () => {
  const items = ['a', 'b', 'c']
  const first = pickOne(seedFrom('pick'), items)
  const second = pickOne(seedFrom('pick'), items)
  assert.equal(first.value, second.value)
  assert.ok(items.includes(first.value))
})

test('rng: pickOne on an empty list yields undefined without advancing', () => {
  const state = seedFrom('empty')
  const picked = pickOne(state, [])
  assert.equal(picked.value, undefined)
  assert.equal(picked.state, state)
})

// ---------------------------------------------------------------------------
// Adjudication
// ---------------------------------------------------------------------------

test('adjudicate: difficulty hints are clamped into the legal band', () => {
  assert.equal(clampDifficulty(-500, 50), 10)
  assert.equal(clampDifficulty(500, 50), 95)
  assert.equal(clampDifficulty(60, 50), 60)
  assert.equal(clampDifficulty(undefined, 42), 42)
  assert.equal(clampDifficulty(Number.NaN, 42), 42)
})

test('adjudicate: an attribute hint cannot invent a sixth attribute', () => {
  assert.equal(clampAttribute('luck', 'mei'), 'mei')
  assert.equal(clampAttribute(undefined, 'tong'), 'tong')
  assert.equal(clampAttribute('zhi', 'mei'), 'zhi')
})

test('adjudicate: outcome bands are ordered and exhaustive', () => {
  assert.equal(outcomeOf(40), OUTCOME.CRITICAL_SUCCESS)
  assert.equal(outcomeOf(20), OUTCOME.CRITICAL_SUCCESS)
  assert.equal(outcomeOf(19), OUTCOME.SUCCESS)
  assert.equal(outcomeOf(0), OUTCOME.SUCCESS)
  assert.equal(outcomeOf(-1), OUTCOME.PARTIAL)
  assert.equal(outcomeOf(-19), OUTCOME.PARTIAL)
  assert.equal(outcomeOf(-20), OUTCOME.FAILURE)
  assert.equal(outcomeOf(-39), OUTCOME.FAILURE)
  assert.equal(outcomeOf(-40), OUTCOME.CRITICAL_FAILURE)
})

test('adjudicate: a hint can never make a check automatic', () => {
  // Attribute 0, worst possible hint, 2000 rolls: some rolls must still fail.
  let state = seedFrom('no-auto')
  let failures = 0
  for (let index = 0; index < 2000; index += 1) {
    const result = check({
      state,
      attrs: { mei: 0, wu: 0, tong: 0, zhi: 0, zheng: 0 },
      attribute: 'mei',
      difficulty: -999 // clamped to 10
    })
    state = result.state
    if (result.outcome !== OUTCOME.CRITICAL_SUCCESS && result.outcome !== OUTCOME.SUCCESS) {
      failures += 1
    }
  }
  assert.ok(failures > 0, 'a difficulty of 10 against attribute 0 must still fail sometimes')
})

test('adjudicate: a hint can never make a check impossible', () => {
  let state = seedFrom('no-impossible')
  let wins = 0
  for (let index = 0; index < 2000; index += 1) {
    const result = check({
      state,
      attrs: { mei: 100 },
      attribute: 'mei',
      difficulty: 99999 // clamped to 95
    })
    state = result.state
    if (result.outcome === OUTCOME.SUCCESS || result.outcome === OUTCOME.CRITICAL_SUCCESS) {
      wins += 1
    }
  }
  assert.ok(wins > 0, 'a difficulty of 95 against attribute 100 must still succeed sometimes')
})

test('adjudicate: engine modifiers are summed, junk is ignored', () => {
  const result = check({
    state: seedFrom('mods'),
    attrs: { mei: 50 },
    attribute: 'mei',
    difficulty: 50,
    modifiers: [{ value: 10 }, { value: -4 }, { value: Number.NaN }, null, { value: 'x' }]
  })
  assert.equal(result.modifierTotal, 6)
})

test('adjudicate: check reports every component it used', () => {
  const result = check({
    state: seedFrom('components'),
    attrs: { tong: 63 },
    attribute: 'tong',
    difficulty: 55,
    modifiers: [{ value: 5, reason: 'test' }]
  })
  assert.equal(result.attribute, 'tong')
  assert.equal(result.attributeValue, 63)
  assert.equal(result.difficulty, 55)
  assert.equal(result.total, result.roll + 63 + 5)
  assert.equal(result.margin, result.total - 55)
  assert.ok(result.roll >= 1 && result.roll <= 100)
})

test('adjudicate: moral weighing involves no randomness at all', () => {
  const options = [
    { id: 'a', label: 'A', effects: { fame: 5 } },
    { id: 'b', label: 'B', effects: { fame: -5 } }
  ]
  const first = weigh(options)
  const second = weigh(options)
  assert.deepEqual(first, second)
  assert.equal(first[0].effects.fame, 5)
})

test('adjudicate: unknown effect keys are dropped, not silently kept', () => {
  // A typo like `famee` must not survive: the model would narrate a gain that
  // never happened.
  const normalised = normaliseEffects({ famee: 99, fame: 3, troops: 7.9 })
  assert.equal(normalised.fame, 3)
  assert.equal(normalised.troops, 7)
  assert.equal(normalised.famee, undefined)
})

test('adjudicate: counters clamp at 0 and 100 without wrapping', () => {
  const counters = { fame: 95, trust: 2, talent: 50 }
  applyEffects(counters, { fame: 20, trust: -50, talent: 0 }, COUNTER_KEYS)
  assert.equal(counters.fame, 100, 'must cap, not wrap')
  assert.equal(counters.trust, 0, 'must floor, not wrap')
})

test('adjudicate: counters and resources never cross-contaminate', () => {
  const counters = { fame: 10, trust: 10, talent: 10 }
  const resources = { gold: 5, grain: 5, troops: 5, hp: 100 }
  applyEffects(counters, { gold: 100, fame: 5 }, COUNTER_KEYS)
  applyEffects(resources, { gold: 100, fame: 5 }, RESOURCE_KEYS)
  assert.equal(counters.fame, 15)
  assert.equal(counters.gold, undefined, 'gold must not land in counters')
  assert.equal(resources.gold, 105)
  assert.equal(resources.fame, undefined, 'fame must not land in resources')
})

test('adjudicate: hp is capped at 100, other resources floor at 0', () => {
  const resources = { gold: 3, grain: 3, troops: 3, hp: 90 }
  applyEffects(resources, { hp: 50, gold: -100 }, RESOURCE_KEYS)
  assert.equal(resources.hp, 100)
  assert.equal(resources.gold, 0)
})

// ---------------------------------------------------------------------------
// Destiny (势)
// ---------------------------------------------------------------------------

test('destiny: the historical branch costs no drift', () => {
  const priced = priceChoice({
    node: {},
    branch: { historical: true },
    state: { drift: 0 },
    resources: { troops: 100, gold: 100, grain: 100 }
  })
  assert.equal(priced.departure, false)
  assert.equal(priced.drift, 0)
})

test('destiny: a departure adds drift but is never refused', () => {
  const priced = priceChoice({
    node: {},
    branch: { historical: false },
    state: { drift: 0 },
    resources: { troops: 100, gold: 100, grain: 100 }
  })
  assert.equal(priced.departure, true)
  assert.equal(priced.drift, DRIFT_PER_DEVIATION)
  assert.ok(priced.reasons.length > 0)
})

test('destiny: free-choice nodes do not count as departures', () => {
  const priced = priceChoice({
    node: { freeChoice: true },
    branch: { historical: false },
    state: { drift: 0 },
    resources: { troops: 0, gold: 0, grain: 0 }
  })
  assert.equal(priced.departure, false)
})

test('destiny: acting beyond your means costs extra drift', () => {
  const rich = priceChoice({
    node: {},
    branch: { historical: false, demand: { troops: 100 } },
    state: { drift: 0 },
    resources: { troops: 100, gold: 0, grain: 0 }
  })
  const poor = priceChoice({
    node: {},
    branch: { historical: false, demand: { troops: 100 } },
    state: { drift: 0 },
    resources: { troops: 0, gold: 0, grain: 0 }
  })
  assert.ok(poor.drift > rich.drift, 'shortfall must cost more')
  assert.ok(poor.shortfall > rich.shortfall)
})

test('destiny: drift is bounded and pressure is capped', () => {
  const priced = priceChoice({
    node: {},
    branch: { historical: false, demand: { troops: 1e9, gold: 1e9, grain: 1e9 } },
    state: { drift: DRIFT_MAX },
    resources: { troops: 0, gold: 0, grain: 0 }
  })
  assert.ok(priced.drift <= DRIFT_MAX)
  assert.ok(Math.abs(priced.pressure.value) <= PRESSURE_CAP)
})

test('destiny: pressure is a modifier, never a veto', () => {
  const pressure = pressureOf(DRIFT_MAX)
  assert.ok(pressure.value <= 0)
  assert.ok(pressure.value >= -PRESSURE_CAP, 'pressure must stay a penalty, not a wall')
})

test('destiny: decay is slow and floored', () => {
  assert.equal(decay({ drift: 10 }).drift, 8)
  assert.equal(decay({ drift: 1 }).drift, 0)
  assert.equal(decay({ drift: 0 }).drift, 0)
})

test('destiny: the world mood is a phrase, not a number', () => {
  assert.equal(describe(0), '天下未觉')
  assert.equal(describe(100), '举世皆敌')
  for (const drift of [5, 20, 45, 70, 90]) {
    assert.ok(typeof describe(drift) === 'string' && describe(drift).length > 0)
  }
})

test('destiny: isDeparture treats a missing historical flag as a departure', () => {
  assert.equal(isDeparture({}, { historical: true }), false)
  assert.equal(isDeparture({}, {}), true)
  assert.equal(isDeparture({ freeChoice: true }, {}), false)
})

// ---------------------------------------------------------------------------
// Clock
// ---------------------------------------------------------------------------

test('clock: four seasons make a year and the age follows the year', () => {
  let clock = { year: 184, month: 1, day: 1, turn: 0 }
  clock = advance(clock, 4)
  assert.equal(clock.year, 185)
  assert.equal(clock.turn, 0)
  assert.equal(clock.age, ageAt(185))
})

test('clock: advancing does not mutate the input clock', () => {
  const clock = { year: 184, month: 1, day: 1, turn: 0 }
  const next = advance(clock, 2)
  assert.equal(clock.year, 184)
  assert.notEqual(next, clock)
})

test('clock: season and month agree for every turn index', () => {
  for (let turn = 0; turn < 4; turn += 1) {
    const clock = advance({ year: 184, turn: 0 }, turn)
    assert.equal(clock.season, seasonOfTurn(turn))
    assert.equal(clock.month, monthOfTurn(turn))
  }
})

test('clock: a negative or junk turn count is treated as zero', () => {
  const clock = { year: 184, turn: 0 }
  assert.equal(advance(clock, -5).year, 184)
  assert.equal(advance(clock, Number.NaN).year, 184)
})

test('clock: ages match the historical record', () => {
  // 刘备 born 161: 184 起兵 is 23, 208 长坂 is 47, 219 汉中王 is 58.
  assert.equal(ageAt(184), 23)
  assert.equal(ageAt(208), 47)
  assert.equal(ageAt(219), 58)
})

test('clock: era labels are readable', () => {
  assert.equal(eraOf(184), '中平元年')
  assert.equal(eraOf(196), '建安元年')
  assert.ok(formatDate({ year: 208, turn: 2 }).includes('208'))
})

test('clock: seasonsUntilAge never goes negative', () => {
  assert.equal(seasonsUntilAge({ age: 47 }, 47), 0)
  assert.equal(seasonsUntilAge({ age: 47 }, 40), 0)
  assert.equal(seasonsUntilAge({ age: 40 }, 47), 28)
})

// ---------------------------------------------------------------------------
// State
// ---------------------------------------------------------------------------

test('state: a fresh save starts at birth, with a Liu Bei who is bad at everything but charm', () => {
  // The run opens in 161 (age 0): the first act is a childhood, and the clock
  // has to be able to show it. `catchUpToScene` fast-forwards to each scene's
  // stamped age, so the player reaches 184 with the right number of years
  // behind him rather than being handed a 23-year-old boy pointing at a tree.
  const state = createSave('liubei')
  assert.equal(state.schema, SCHEMA)
  assert.equal(state.clock.year, 161)
  assert.equal(state.age, 0)
  assert.ok(state.player.attrs.mei > 70, 'charm is the one high attribute')
  for (const key of ['wu', 'tong', 'zhi', 'zheng']) {
    assert.ok(state.player.attrs[key] < 60, `${key} must be mediocre`)
  }
  assert.equal(state.player.resources.troops, 0)
})

test('state: the same name gives the same seed', () => {
  assert.equal(createSave('a').seed, createSave('a').seed)
  assert.notEqual(createSave('a').seed, createSave('b').seed)
})

test('state: migrate fills defaults into an old save', () => {
  const old = { schema: 0, clock: { year: 190, turn: 2 }, player: { attrs: { mei: 80 } } }
  const migrated = migrate(old)
  assert.equal(migrated.schema, SCHEMA)
  assert.equal(migrated.clock.year, 190)
  assert.equal(migrated.player.attrs.mei, 80)
  assert.ok(migrated.player.attrs.wu > 0, 'missing attributes get defaults')
  assert.ok(Array.isArray(migrated.log))
  assert.ok(migrated.factions === undefined || typeof migrated.factions === 'object')
})

test('state: migrate clamps out-of-range values instead of resetting them', () => {
  const migrated = migrate({ player: { attrs: { mei: 500 }, counters: { fame: -20 }, resources: { gold: -5 } } })
  assert.equal(migrated.player.attrs.mei, 100)
  assert.equal(migrated.player.counters.fame, 0)
  assert.equal(migrated.player.resources.gold, 0)
})

test('state: save/load round-trips exactly', async () => {
  const dir = mkdtempSync(join(tmpdir(), 'sanguo-state-'))
  const state = seedFactions(createSave('roundtrip'))
  await save(dir, state)
  const loaded = await load(dir)
  assert.deepEqual(loaded, migrate(state))
  assert.equal(await exists(dir), true)
})

test('state: load returns null when there is no save', async () => {
  const dir = mkdtempSync(join(tmpdir(), 'sanguo-empty-'))
  assert.equal(await load(dir), null)
  assert.equal(await exists(dir), false)
})

test('state: a corrupt save is reported, never silently replaced', async () => {
  const dir = mkdtempSync(join(tmpdir(), 'sanguo-corrupt-'))
  mkdirSync(join(dir, '.sanguo'), { recursive: true })
  writeFileSync(join(dir, '.sanguo', 'save.json'), '{ not json', 'utf8')
  await assert.rejects(() => load(dir), /存档已损坏/)
})

test('state: history is append-only and readable', async () => {
  const dir = mkdtempSync(join(tmpdir(), 'sanguo-history-'))
  await appendHistory(dir, { kind: 'a' })
  await appendHistory(dir, { kind: 'b' })
  const records = await readHistory(dir)
  assert.equal(records.length, 2)
  assert.equal(records[0].kind, 'a')
  assert.equal(records[1].kind, 'b')
})

test('state: a torn final history line is skipped, not fatal', async () => {
  const dir = mkdtempSync(join(tmpdir(), 'sanguo-torn-'))
  await appendHistory(dir, { kind: 'good' })
  const path = join(dir, '.sanguo', 'history.jsonl')
  writeFileSync(path, readFileSync(path, 'utf8') + '{"kind": "torn', 'utf8')
  const records = await readHistory(dir)
  assert.equal(records.length, 1)
})

// ---------------------------------------------------------------------------
// People
// ---------------------------------------------------------------------------

test('people: disposition derives from memories, not from a slider', () => {
  const person = instantiate('guanyu', 0)
  assert.equal(dispositionOf(person), 0)
  const kinder = remember(person, { kind: 'kindness', text: '同寝', turn: 0 })
  assert.ok(dispositionOf(kinder) > 0)
  const betrayed = remember(kinder, { kind: 'betrayal', text: '弃之', turn: 1 })
  assert.ok(dispositionOf(betrayed) < dispositionOf(kinder))
})

test('people: disposition is bounded to [-100, 100]', () => {
  let person = instantiate('guanyu', 0)
  for (let index = 0; index < 40; index += 1) {
    person = remember(person, { kind: 'oath', text: '誓', turn: index })
  }
  assert.ok(dispositionOf(person) <= 100)
  assert.ok(dispositionOf(person) >= -100)
})

test('people: memories are capped and the newest survive', () => {
  let person = instantiate('guanyu', 0)
  for (let index = 0; index < MEMORY_LIMIT + 5; index += 1) {
    person = remember(person, { kind: 'kindness', text: `m${index}`, turn: index })
  }
  assert.equal(person.memories.length, MEMORY_LIMIT)
  assert.equal(person.memories[person.memories.length - 1].text, `m${MEMORY_LIMIT + 4}`)
})

test('people: unknown ids are refused rather than invented', () => {
  assert.equal(instantiate('nobody', 0), null)
  const state = seedFactions(createSave('x'))
  const result = ensurePerson(state, 'nobody')
  assert.equal(result.person, null)
  assert.equal(result.state, state)
})

test('people: stance labels are ordered from warm to hostile', () => {
  assert.equal(stanceLabel(80), '死心塌地')
  assert.equal(stanceLabel(0), '平淡')
  assert.equal(stanceLabel(-80), '誓不两立')
})

test('people: every shipped person has the five attributes', () => {
  for (const id of Object.keys(PEOPLE)) {
    const person = instantiate(id)
    for (const key of ['wu', 'tong', 'zhi', 'zheng', 'mei']) {
      assert.ok(Number.isFinite(person.attrs[key]), `${id} missing ${key}`)
    }
  }
})

test('people: seasonal mood drift is deterministic and only touches known moods', () => {
  const state = seedFactions(createSave('moods'))
  const seeded = ensurePerson(state, 'guanyu')
  const first = driftMoods(seeded.state)
  const second = driftMoods(seeded.state)
  assert.deepEqual(first.people.guanyu.mood, second.people.guanyu.mood)
  assert.ok(['calm', 'wary', 'warm', 'cold', 'hostile', 'calculating'].includes(first.people.guanyu.mood))
})

// ---------------------------------------------------------------------------
// Digest
// ---------------------------------------------------------------------------

test('digest: only met people appear, ordered by how much they care', () => {
  let state = seedFactions(createSave('digest'))
  state = ensurePerson(state, 'guanyu', 30).state
  state = ensurePerson(state, 'duyou', -40).state
  const people = nearestPeople(state)
  assert.equal(people.length, 2)
  assert.equal(people[0].name, '督邮', 'the one who cares most (negatively) comes first')
})

test('digest: unmet people are hidden', () => {
  const state = seedFactions(createSave('unmet'))
  assert.deepEqual(nearestPeople(state), [])
})

test('digest: recent events are capped', () => {
  let state = createSave('events')
  for (let index = 0; index < 30; index += 1) {
    state = pushLog(state, { kind: 'x', text: `e${index}` })
  }
  assert.equal(recentEvents(state).length, LIMITS.recentEvents)
  assert.equal(recentEvents(state).at(-1), 'e29')
})

test('digest: the digest carries the three counters and the world mood', () => {
  const digest = buildDigest(seedFactions(createSave('d')), {})
  assert.equal(digest.me.counters.fame, 5)
  assert.equal(typeof digest.world.mood, 'string')
  assert.ok(digest.when.length > 0)
})

test('digest: extra payload is attached without mutating the base', () => {
  const state = seedFactions(createSave('extra'))
  const withOptions = buildDigest(state, { options: [{ id: 'a' }], outcome: { x: 1 } })
  const plain = buildDigest(state, {})
  assert.equal(withOptions.options.length, 1)
  assert.equal(plain.options, undefined)
})

test('digest: 势 means drift only, and 实力 means the player rating', () => {
  // The first render said "势 34" for the player's power while the world mood
  // said 天下未觉 (drift 0) — two different quantities under one word.
  const state = { ...seedFactions(createSave('terms')), clock: { year: 184, turn: 0 }, age: 23, drift: 12 }
  const text = renderDigest(buildDigest(state, {}))
  assert.ok(text.includes('实力'), 'the player rating must be called 实力')
  assert.ok(text.includes('势 12'), '势 must carry the drift value')
  assert.equal((text.match(/势/g) ?? []).length, 1, 'the word 势 appears once, meaning drift')
})

test('digest: renders to readable text', () => {
  const state = { ...seedFactions(createSave('render')), clock: { year: 184, turn: 0 }, age: 23 }
  const text = renderDigest(buildDigest(state, {}))
  assert.ok(text.includes('23岁'))
  assert.ok(text.includes('名望'))
})

// ---------------------------------------------------------------------------
// Acts
// ---------------------------------------------------------------------------

const ACTS_DOC = JSON.parse(
  readFileSync(new URL('../data/acts.json', import.meta.url), 'utf8')
)

test('acts: the act table is well formed', () => {
  const acts = indexActs(ACTS_DOC)
  assert.ok(acts.size >= 7, 'at least seven acts shipped')
  for (const [id, act] of acts) {
    assert.ok(Array.isArray(act.scenes) && act.scenes.length > 0, `${id} has scenes`)
    for (const scene of act.scenes) {
      assert.ok(['moral', 'ability', 'free'].includes(scene.kind), `${id}/${scene.id} kind`)
      if (scene.kind === 'moral') {
        assert.ok(Array.isArray(scene.options) && scene.options.length >= 2, `${id}/${scene.id} options`)
        const ids = new Set()
        for (const option of scene.options) {
          assert.ok(typeof option.id === 'string' && option.id.length > 0)
          assert.ok(!ids.has(option.id), `${id}/${scene.id} duplicate option id ${option.id}`)
          ids.add(option.id)
          assert.ok(typeof option.label === 'string' && option.label.length > 0)
        }
        // Every moral node must record which branch history took, so drift can
        // be priced. Without it every choice would look like a departure.
        assert.equal(
          scene.options.filter((option) => option.historical === true).length, 1,
          `${id}/${scene.id} must mark exactly one historical branch`
        )
      }
      if (scene.kind === 'ability') {
        assert.ok(Number.isFinite(scene.difficulty), `${id}/${scene.id} difficulty`)
        assert.ok(typeof scene.attribute === 'string', `${id}/${scene.id} attribute`)
        assert.ok(scene.effects?.success !== undefined, `${id}/${scene.id} success effects`)
        assert.ok(scene.effects?.failure !== undefined, `${id}/${scene.id} failure effects`)
      }
    }
  }
})

