test('acts: the cursor advances through scenes then acts', () => {
  const acts = indexActs(ACTS_DOC)
  let state = seedFactions(createSave('cursor'))
  const firstAct = state.act
  const first = currentScene(state, acts)
  state = nextCursor(state, acts)
  assert.equal(state.act, firstAct)
  assert.equal(state.scene, 1)

  // Jump to the last scene of the act and advance again: act must change.
  const act = acts.get(firstAct)
  state = { ...state, scene: act.scenes.length - 1 }
  const after = nextCursor(state, acts)
  assert.notEqual(after.act, firstAct)
})

