test('acts: an act the player is too young for is fast-forwarded, never skipped', () => {
  const acts = indexActs(ACTS_DOC)
  const state = {
    ...seedFactions(createSave('young')),
    act: 'zhuojun',
    scene: 3,
    clock: { year: 166, turn: 0 },
    age: 5
  }
  const next = nextCursor(state, acts)
  // Skipping would delete a chapter of the life, which is the one thing this
  // game is about. The clock is pushed to the act's opening age instead.
  assert.equal(next.act, 'anxi')
  assert.ok(next.age >= 23, `expected age >= 23, got ${next.age}`)
  assert.ok(next.clock.year >= 184)
})

test('acts: a fast-forwarded act does not invent a shortcut through the calendar', () => {
  const acts = indexActs(ACTS_DOC)
  // Age is DERIVED from the clock, so a consistent 20-year-old is clock year
  // 181. Setting `age: 20` on a 184 clock would be an inconsistent save, and
  // the engine (correctly) trusts the clock.
  // Sitting on the LAST scene of 涿郡 (which ends at 23) with a clock that says
  // 20: advancing must move the calendar three years, not skip ahead.
  const base = seedFactions(createSave('young2'))
  const state = {
    ...base,
    act: 'zhuojun',
    scene: 3,
    clock: { year: 181, month: 1, day: 1, turn: 0 },
    age: 20
  }
  const next = nextCursor(state, acts)
  // 20 -> 23 is three years, so the clock must move exactly three years.
  assert.equal(next.age, 23)
  assert.equal(next.clock.year, 184)
})

